import{_ as e,c as a,o as i,j as n,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const k=JSON.parse('{"title":"time | x-cmd man (man1) | time a simple command or give resource usage","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | time - time a simple command or give resource usage","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"time | x-cmd man (man1) | time a simple command or give resource usage"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | time - time a simple command or give resource usage"}]]},"headers":[],"params":{"isMan":true,"man":"time","category":"man1","desc":"time a simple command or give resource usage"},"relativePath":"man1/time.md","filePath":"man1/[man].md"}'),d={name:"man1/time.md"},h={class:"visually-hidden"};function l(s,t,m,p,g,u){return i(),a("div",null,[n("h1",h,r(s.$params.man),1),t[0]||(t[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>time - time a simple command or give resource usage</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>time</strong> [<em>option</em> . . .]* command *[<em>argument</em> . . .]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>time</strong> command runs the specified program <em>command</em> with the given arguments. When <em>command</em> finishes, <strong>time</strong> writes a message to standard error giving timing statistics about this program run. These statistics consist of (i) the elapsed real time between invocation and termination, (ii) the user CPU time (the sum of the <em>tms_utime</em> and <em>tms_cutime</em> values in a <em>struct tms</em> as returned by <strong>times</strong>(2)), and (iii) the system CPU time (the sum of the <em>tms_stime</em> and <em>tms_cstime</em> values in a <em>struct tms</em> as returned by <strong>times</strong>(2)).</p><p>Note: some shells (e.g., <strong>bash</strong>(1)) have a built-in <strong>time</strong> command that provides similar information on the usage of time and possibly other resources. To access the real command, you may need to specify its pathname (something like <em>/usr/bin/time</em>).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><dl><dt><strong>-p</strong></dt><dd>When in the POSIX locale, use the precise traditional format</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;real %f\\nuser %f\\nsys %f\\n&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">with</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> numbers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">where</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> number</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> of</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decimals</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> %f is unspecified but is sufficient to express the clock tick</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">accuracy,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> least</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> one.</span></span></code></pre></div><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>If <em>command</em> was invoked, the exit status is that of <em>command</em>. Otherwise, it is 127 if <em>command</em> could not be found, 126 if it could be found but could not be invoked, and some other nonzero value (1--125) if something else went wrong.</p><h2 id="environment" tabindex="-1">ENVIRONMENT <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;ENVIRONMENT&quot;">​</a></h2><p>The variables <strong>LANG</strong>, <strong>LC_ALL</strong>, <strong>LC_CTYPE</strong>, <strong>LC_MESSAGES</strong>, <strong>LC_NUMERIC</strong>, and <strong>NLSPATH</strong> are used for the text and formatting of the output. <strong>PATH</strong> is used to search for <em>command</em>.</p><h2 id="gnu-version" tabindex="-1">GNU VERSION <a class="header-anchor" href="#gnu-version" aria-label="Permalink to &quot;GNU VERSION&quot;">​</a></h2><p>Below a description of the GNU 1.7 version of <strong>time</strong>. Disregarding the name of the utility, GNU makes it output lots of useful information, not only about time used, but also on other resources like memory, I/O and IPC calls (where available). The output is formatted using a format string that can be specified using the <em>-f</em> option or the <strong>TIME</strong> environment variable.</p><p>The default format string is:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">%Uuser</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %Ssystem</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %Eelapsed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %PCPU</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (%Xtext+%Ddata </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">%Mmax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)k</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">%Iinputs+%Ooutputs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (%Fmajor+%Rminor)pagefaults %Wswaps</span></span></code></pre></div><p>When the <em>-p</em> option is given, the (portable) output format is used:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">real</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %e</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %U</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %S</span></span></code></pre></div><h3 id="the-format-string" tabindex="-1">The format string <a class="header-anchor" href="#the-format-string" aria-label="Permalink to &quot;The format string&quot;">​</a></h3><p>The format is interpreted in the usual printf-like way. Ordinary characters are directly copied, tab, newline, and backslash are escaped using \\t, \\n, and \\\\, a percent sign is represented by %%, and otherwise % indicates a conversion. The program <strong>time</strong> will always add a trailing newline itself. The conversions follow. All of those used by <strong>tcsh</strong>(1) are supported.</p><p><strong>Time</strong></p><dl><dt><strong>%E</strong></dt><dd>Elapsed real time (in [hours:]minutes:seconds).</dd><dt><strong>%e</strong></dt><dd>(Not in <strong>tcsh</strong>(1).) Elapsed real time (in seconds).</dd><dt><strong>%S</strong></dt><dd>Total number of CPU-seconds that the process spent in kernel mode.</dd><dt><strong>%U</strong></dt><dd>Total number of CPU-seconds that the process spent in user mode.</dd><dt><strong>%P</strong></dt><dd>Percentage of the CPU that this job got, computed as (%U + %S) / %E.</dd></dl><p><strong>Memory</strong></p><dl><dt><strong>%M</strong></dt><dd>Maximum resident set size of the process during its lifetime, in Kbytes.</dd><dt><strong>%t</strong></dt><dd>(Not in <strong>tcsh</strong>(1).) Average resident set size of the process, in Kbytes.</dd><dt><strong>%K</strong></dt><dd>Average total (data+stack+text) memory use of the process, in Kbytes.</dd><dt><strong>%D</strong></dt><dd>Average size of the process&#39;s unshared data area, in Kbytes.</dd><dt><strong>%p</strong></dt><dd>(Not in <strong>tcsh</strong>(1).) Average size of the process&#39;s unshared stack space, in Kbytes.</dd><dt><strong>%X</strong></dt><dd>Average size of the process&#39;s shared text space, in Kbytes.</dd><dt><strong>%Z</strong></dt><dd>(Not in <strong>tcsh</strong>(1).) System&#39;s page size, in bytes. This is a per-system constant, but varies between systems.</dd><dt><strong>%F</strong></dt><dd>Number of major page faults that occurred while the process was running. These are faults where the page has to be read in from disk.</dd><dt><strong>%R</strong></dt><dd>Number of minor, or recoverable, page faults. These are faults for pages that are not valid but which have not yet been claimed by other virtual pages. Thus the data in the page is still valid but the system tables must be updated.</dd><dt><strong>%W</strong></dt><dd>Number of times the process was swapped out of main memory.</dd><dt><strong>%c</strong></dt><dd>Number of times the process was context-switched involuntarily (because the time slice expired).</dd><dt><strong>%w</strong></dt><dd>Number of waits: times that the program was context-switched voluntarily, for instance while waiting for an I/O operation to complete.</dd></dl><p><strong>I/O</strong></p><dl><dt><strong>%I</strong></dt><dd>Number of filesystem inputs by the process.</dd><dt><strong>%O</strong></dt><dd>Number of filesystem outputs by the process.</dd><dt><strong>%r</strong></dt><dd>Number of socket messages received by the process.</dd><dt><strong>%s</strong></dt><dd>Number of socket messages sent by the process.</dd><dt><strong>%k</strong></dt><dd>Number of signals delivered to the process.</dd><dt><strong>%C</strong></dt><dd>(Not in <strong>tcsh</strong>(1).) Name and command-line arguments of the command being timed.</dd><dt><strong>%x</strong></dt><dd>(Not in <strong>tcsh</strong>(1).) Exit status of the command.</dd></dl><h3 id="gnu-options" tabindex="-1">GNU options <a class="header-anchor" href="#gnu-options" aria-label="Permalink to &quot;GNU options&quot;">​</a></h3><dl><dt><strong>-f</strong> <em>format</em>* <em>, --format=</em>* <em>format</em></dt><dd>Specify output format, possibly overriding the format specified in the environment variable TIME.</dd><dt><strong>-p, --portability</strong></dt><dd>Use the portable output format.</dd><dt><strong>-o</strong> <em>file</em>* <em>, --output=</em>* <em>file</em></dt><dd>Do not send the results to <em>stderr</em>, but overwrite the specified file.</dd><dt><strong>-a, --append</strong></dt><dd>(Used together with -o.) Do not overwrite but append.</dd><dt><strong>-v, --verbose</strong></dt><dd>Give very verbose output about all the program knows about.</dd><dt><strong>-q, --quiet</strong></dt><dd>Don&#39;t report abnormal program termination (where <em>command</em> is terminated by a signal) or nonzero exit status.</dd></dl><h3 id="gnu-standard-options" tabindex="-1">GNU standard options <a class="header-anchor" href="#gnu-standard-options" aria-label="Permalink to &quot;GNU standard options&quot;">​</a></h3><dl><dt><strong>--help</strong></dt><dd>Print a usage message on standard output and exit successfully.</dd><dt><strong>-V, --version</strong></dt><dd>Print version information on standard output, then exit successfully.</dd><dt><strong>--</strong></dt><dd>Terminate option list.</dd></dl><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Not all resources are measured by all versions of UNIX, so some of the values might be reported as zero. The present selection was mostly inspired by the data provided by 4.2 or 4.3BSD.</p><p>GNU time version 1.7 is not yet localized. Thus, it does not implement the POSIX requirements.</p><p>The environment variable <strong>TIME</strong> was badly chosen. It is not unusual for systems like <strong>autoconf</strong>(1) or <strong>make</strong>(1) to use environment variables with the name of a utility to override the utility to be used. Uses like MORE or TIME for options to programs (instead of program pathnames) tend to lead to difficulties.</p><p>It seems unfortunate that <em>-o</em> overwrites instead of appends. (That is, the <em>-a</em> option should be the default.)</p><p>Mail suggestions and bug reports for GNU <strong>time</strong> to <em><a href="mailto:bug-time@gnu.org" target="_blank" rel="noreferrer">bug-time@gnu.org</a></em>. Please include the version of <strong>time</strong>, which you can get by running</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --version</span></span></code></pre></div><p>and the operating system and C compiler you used.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>bash</strong>(1), <strong>tcsh</strong>(1), <strong>times</strong>(2), <strong>wait3</strong>(2)</p>`,42))])}const f=e(d,[["render",l]]);export{k as __pageData,f as default};
